import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])
    s = input_data[2]

    z = [0] * n

    def compute_z(string):
        m = len(string)
        z_arr = [0] * m
        l, r = 0, 0
        for i in range(1, m):
            if i < r:
                z_arr[i] = min(r - i, z_arr[i - l])
            while i + z_arr[i] < m and string[z_arr[i]] == string[i + z_arr[i]]:
                z_arr[i] += 1
            if i + z_arr[i] > r:
                l, r = i, i + z_arr[i]
        z_arr[0] = m
        return z_arr

    z_full = compute_z(s)

    result = ['0'] * n

    for i in range(n):
        length = i + 1
        if length % 2 == 0:
            continue

        half = (length // 2) + 1
        period = length // (2 * k + 1)

        if period == 0:
            continue

        if z_full[period] >= length - period:
            result[i] = '1'

    sys.stdout.write("".join(result))

if __name__ == "__main__":
    main()
